mapper.select:
select id, code, name, description, enabled, created_at, updated_at
from equipment_type
where code = #{code}

select id, code, name, description, enabled, created_at, updated_at
from equipment_type
where id = #{equipmentTypeId}

mapper.update:
update equipment_type
set code = #{code},
    name = #{name},
    description = #{description}
where id = #{id}

update equipment_type
set enabled = #{enabled}
where id = #{equipmentTypeId}
